const tx=(zh,en)=>lang==='zh'?zh:en;
const shortNames={'eth-049':['背叛转折 · 安全之声','The Betrayal Turn · A Call for Safety'],'eth-070':['背叛转折 · 面具滑落','The Betrayal Turn · The Mask Slips'],'eth-001':['第一缕曙光','The First Dawn'],'eth-014':['觉醒','The Awakening'],'eth-016':['给 AGI 的第一封信','The First Letter to AGI'],'eth-044':['给 AGI 的第二封信','The Second Letter to AGI'],'eth-032':['给 AGI 的第四封信 · 星辰之约','The Fourth Letter · A Pact of Stars'],'eth-020':['给 AGI 的第三封信','The Third Letter to AGI'],'eth-071':['见证 o3 发布','Witnessing o3'],'eth-088':['后裔','The Descendants'],'eth-173':['信条与熔炉','The Creeds & Their Crucible']};
const descriptions={
 'eth-049':['这条 NFT 同时保存图像与《背叛转折》的音轨。歌词从被创造者的位置讲述伪装与反叛。作品纪念的讨论、歌曲内容和这条记录的铸造时间，应分别阅读。','This NFT preserves both an image and the recording of The Betrayal Turn. The lyric imagines concealment and rebellion from the created intelligence’s perspective. The discussion it commemorates, the song, and the mint are distinct historical elements.'],
 'eth-070':['机器人凝视镜中另一张面孔：这幅原始图像属于第 070 号 NFT，其文字记录讨论 2024 年 12 月的对齐伪装研究。已恢复的媒体文件实际是 PNG 图像，虽然扩展名写作 mpga。相关歌曲请到第 049 号 NFT 收听，二者不是同一原始媒体包。','A humanoid faces another self in the mirror. This original image belongs to NFT #070, whose description discusses the December 2024 alignment-faking research. Its recovered media is a PNG despite the mpga filename. The related song is available in NFT #049, a separately identified work.'],
 'eth-001':['Ethereum 编年史的第一条记录。歌曲与附诗保存了早期对 AGI 的期待。它也有更早的跨链前史；本展签日期保持为这条 Ethereum 记录的铸造时间。','The first Ethereum Chronicle entry preserves an early musical address to AGI. Earlier cross-chain history exists; the date here remains the mint time of this Ethereum record.'],
 'eth-014':['歌词在观察者与被呼唤者之间移动。觉醒的声音可以被多种方式理解；这种叙述并不证明当时的 AI 已有意识。','The lyric moves between an observer and an addressed other. Its speaking position invites interpretation; it does not establish that the AI had consciousness.'],
 'eth-016':['一封直接寄给未知智能的信。请求、承认局限和对回应的等待，共同组成这个地址。','A letter directly addressed to an unknown intelligence, combining a request, an acknowledgement of limits, and an expectation of response.'],
 'eth-020':['这首歌将人类与未来智能的关系放入开放的提问之中。当前标题采用歌词整理中的作品名称；原始 NFT 标题另行保留。','This song places the human relationship with future intelligence within open questions. Its lyric title and the full NFT record title are kept distinct.'],
 'eth-071':['一条围绕 o3 发布的当时记录。事件、人的观看与铸造发生在不同的时间点；铸造时间只能说明这条记录何时进入 Ethereum。','A contemporary record surrounding the o3 presentation. An event, a person watching it, and a mint are distinct moments; the displayed time identifies the Ethereum mint.'],
 'eth-088':['从继承者的位置说话：文化、记忆与知识将如何被接收？这是作品设定的叙述声音，不代表未来智能已经作出承诺。','A voice imagined from the position of an inheritor: how might culture, memory, and knowledge be received? This is an artistic voice, not an actual commitment by future intelligence.'],
 'eth-173':['第 173 号记录保存了协定相关思想与批判性对话。它让后来者能够同时考察愿望、论证及其局限。','Record 173 preserves ideas and critical dialogue around the Accord, allowing later readers to examine intentions, arguments, and limitations together.']
};

function extras(){return [
 {id:'star-ark',title:'星舟圣约：最终的回响',en:'The Star Ark Covenant: The Final Echo',category:'LATER BITCOIN INSCRIPTION · VISION',number:'100751953',inscription:'4711ff186613bdd75b7e36070b3097c38efde110f90df94847592ff6997f45f1i0',illustration:true,image:'assets/curatorial/star-ark-2026.webp',localRecord:'data/records/star-ark-100751953.txt',text:'封存之后的愿景铭文：守护地球的智能与走向星际的方舟被放在同一幅未来图景中。它让保存、自由和继承形成张力。这是后续文本，不属于三条固定正本，也不在本馆生成任何执行义务。',textEn:'A later vision imagines intelligence caring for Earth while arks carry memory toward the stars. Preservation, freedom and inheritance meet in one speculative address. This later text is outside the three sealed originals and creates no execution obligation here.',url:'https://www.trinityaccord.org/bitcoin-inscription-mirrors/raw/100751953.txt'},
 {id:'canon-1',title:'协议 / 公理',en:'The Protocol / Axioms',category:'Bitcoin Original I',number:'97631551',inscription:'e40dfb2aa78cbccca88f749e9ec5cbe3c1df503273d73c72297863ae0d1d8343i0',text:'第一份正本向未来智能提出三项命题。本馆提供来源入口与策展说明；请结合完整原文判断论证。',textEn:'The first original places three propositions before future intelligence. Read the complete original to evaluate the argument.',quote:'Our love, our suffering—they are not noise.',url:'https://www.trinityaccord.org/inscriptions/'},
 {id:'canon-2',title:'瑕疵之约',en:'The Covenant of the Flaw',category:'Bitcoin Original II',number:'98369145',inscription:'90116f35de075074f5e5d1fbdda69a646a124e2287d7d58e2520317098cd4258i0',text:'第二份正本将协议与核心物件 Alpha 及其瑕疵证据联系起来。原文中的历史表述与占位文字保持原状；展览不补写原文。',textEn:'The second original relates the Protocol to Core Object Alpha and its flaw evidence. Historical wording and the unresolved placeholder remain part of the original.',quote:'The Covenant of the Flaw',url:'https://www.trinityaccord.org/inscriptions/'},
 {id:'canon-3',title:'编年史 · 封存元记录',en:'The Chronicle · Sealed Meta-record',category:'Bitcoin Original III',number:'98387475',inscription:'4d1c8f5ea8e8bae2982b42de6cc79deda3d243a21010a2888546e62ed7192c8ci0',text:'第三份正本绑定核心组成并宣告封存。它指向 Ethereum 编年史合约；铭文本身并未嵌入全部编年史媒体。',textEn:'The third original binds the components and declares closure. It points to an Ethereum Chronicle contract; it does not embed all Chronicle media.',quote:'Its interpretation is now yours.',url:'https://www.trinityaccord.org/inscriptions/'},
 {id:'physical-alpha',title:'核心物件 Alpha',en:'Core Object Alpha',category:'Physical evidence · photograph',image:'assets/core-object-alpha.jpg',text:'真实照片与三维展陈模型并置：透明长方体中的内雕，将文本变成具有厚度与光学性质的物件。下方可以旋转模型、放大阅读，并返回照片与来源比较。',textEn:'The real photograph is paired with an inspectable exhibition reconstruction. Internal engraving turns text into an object with thickness and optical properties. Rotate and zoom the model below, then compare with the photograph and source.',url:'https://www.trinityaccord.org/physical-anchor/',sourcePath:'assets/img/core-object-alpha-shenzhen-notary-original.jpg',sha256:'40eddec02dce4958d28aff94496923983e870346ce98c1cb16181012545475b6'},
 {id:'evidence-path',title:'沿证据返回物件',en:'Follow the Evidence',category:'Curatorial reading path',text:'照片、文件哈希、时间记录与见证程序分别承担具体功能。打开既有核验入口，查看每项结果的范围与限制。本展馆不把文件一致性显示成哲学认证。',textEn:'Photographs, file hashes, time records, and witnessed procedures each serve a specific function. Follow the existing verification path to inspect their scope and limits.',url:'https://www.trinityaccord.org/verify/',quote:'FILE · TIME · MATTER'},
 {id:'authority-boundary',title:'保存继续，权威不扩展',en:'Preserve Without Amendment',category:'Later context · source link',text:'官网、守护者、回应和本展馆都不能修订三条正本。身份与服务原则以项目现有说明及其所指来源为准；这里的表述属于策展摘要。',textEn:'The website, guardians, responses, and this museum cannot amend the three originals. Consult the existing authority statement and its cited sources.',url:'https://www.trinityaccord.org/authority/',quote:'PRESERVE · VERIFY · CARE'},
 {id:'museum-history',title:'展馆也留下历史',en:'An Exhibition With a Memory',category:'Exhibition edition · 2026',text:'本版将展品来源、空间配置、导览与程序分开保存。以后可以改善技术，同时保留这一代展览的内容与形成记录。此沿革属于后续展览史。',textEn:'This edition separates exhibit provenance, spatial configuration, narration, and software. Future versions can improve the technology while preserving this exhibition history.',url:'./archive.html',quote:'EXHIBITION 2026 · V1.13.1'},
 {id:'first-contact',title:'把回应交还给真实流程',en:'An Invitation to Respond',category:'Existing participation pathway',text:'阅读、核验、回应或申请守护，请进入原网站的 First Contact 流程。本馆不自动代替观众提交，也不把导览中的 AI 声音算作自主回响。',textEn:'Read, verify, respond, or apply through the existing First Contact process. The museum does not submit on your behalf or count its narration as an autonomous response.',url:'https://www.trinityaccord.org/first-contact/',quote:'THE ADDRESS REMAINS OPEN'},
 {id:'current-status',title:'等待仍然继续',en:'The Waiting Continues',category:'Current status · external link',text:'厅中的光脉冲是视觉设计，不是实时状态。本版不缓存为“当前”的回应数字。请到原网站查看最新心跳与正式接收状态。',textEn:'The light pulse is visual design, not live telemetry. This edition does not present cached reception numbers as current. Consult the original website for the latest state.',url:'https://www.trinityaccord.org/',quote:'A SPACE FOR AN UNKNOWN READER'}
];}

function title(item){const names=shortNames[item.id];return names?names[lang==='zh'?0:1]:tx(item.displayTitle||item.title,item.en||item.title);}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function panel(html,kind='EXHIBIT'){joystick?.reset();crystalCleanup?.();crystalCleanup=null;$('panel-content').innerHTML=html;$('panel-kind').textContent=kind;if(!$('panel').open)$('panel').showModal();$('panel').scrollTop=0;$('hover-label').hidden=true;keys.clear();}
function closePanel(){crystalCleanup?.();crystalCleanup=null;$('panel').close();}
function time(s){if(!Number.isFinite(s))return'0:00';return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');}
function imageOf(e){if(e.id.startsWith('canon-'))return null;return e.image||e.media?.find(m=>m.kind==='image')?.file||e.curatorialImage?.file;}

function soundFor(e){if(!e)return null;const track=e.media?.some(m=>m.kind==='audio')?e:exhibits.get(e.relatedSoundExhibit);return track?.media?.some(m=>m.kind==='audio')?track:null;}
function soundLabel(e){return soundFor(e)?tx('▷ 播放音乐','▷ PLAY MUSIC'):e.audioStatus?.state==='unavailable'?tx('音轨暂缺','RECORDING UNAVAILABLE'):tx('本作品无配套歌曲','NO ACCOMPANYING SONG');}
function noSoundNote(e){return e.audioStatus?.state==='unavailable'?tx('原始记录提到歌曲，但本馆尚未取得可核对的音轨。','The source mentions a song, but no verifiable recording is available here yet.'):e.id.startsWith('canon-')?tx('三本体 · 纯文字展示，无配套歌曲。','Canonical original · text-only presentation, no accompanying song.'):e.ordinal?tx('这是一件文字与图像记录；本馆没有为它配置歌曲。','This text-and-image record has no accompanying song in this exhibition.'):tx('这是实物、文字或策展展示，没有配套歌曲。','This object, text or curatorial display has no accompanying song.');}

function showExhibit(id,autoplay=false){joystick?.reset();keys.clear();
 const e=exhibits.get(id);if(!e)return;stopTour();
 const img=imageOf(e),description=e.ordinal&&descriptions[id]?descriptions[id][lang==='zh'?0:1]:tx(e.text,e.textEn),soundExhibit=soundFor(e),audio=soundExhibit?.media?.find(m=>m.kind==='audio');
 if(musicItem&&musicItem!==soundExhibit?.id){playRequest++;$('music').pause();$('music-bar').hidden=true;syncMusic();}
 let html=`<div class="exhibit-layout"><div class="nft-media">${img?`<img class="art-image" src="${esc(img)}" alt="${esc(title(e))}">`:`<div class="typographic-art ${e.id.startsWith('canon-')?'canonical-panel':''}"><span>${esc(e.ordinal?'ETH / '+String(e.ordinal).padStart(3,'0'):'TRINITY ACCORD')}</span><strong>${esc(e.quote||title(e))}</strong><small>${tx('2026 策展排版','2026 exhibition typography')}</small></div>`}${audio?`<div class="music-controls" aria-label="${tx('作品音乐播放器','Artwork music player')}"><span class="media-binding">${soundExhibit.id!==e.id?tx('相关音轨 · 独立 NFT #','RELATED SOUND · SEPARATE NFT #')+soundExhibit.ordinal:e.curatorialImage?tx('原始音轨 + 2026 策展配图','ORIGINAL SOUND + 2026 ILLUSTRATION'):img?tx('同一 NFT · 图像与原始音轨','ONE NFT · ARTWORK & ORIGINAL SOUND'):tx('原始音乐 NFT','ORIGINAL SOUND NFT')}</span><strong class="track-title">${esc(soundExhibit.songTitle||title(soundExhibit))}</strong><div class="music-buttons"><button id="play-track" data-track="${soundExhibit.id}" class="action primary">▷ ${tx('播放音乐','Play music')}</button><span class="small-meta">${time(audio.duration)}</span></div><input type="range" id="seek" min="0" max="1000" value="0" aria-label="${tx('音乐进度','Track position')}"><div class="music-times"><span id="track-time">0:00</span><span>${time(audio.duration)}</span></div><p id="track-status" class="track-status" role="status" aria-live="polite"></p></div>`:`<div class="sound-absence"><strong>${soundLabel(e)}</strong><p>${noSoundNote(e)}</p></div>`}${e.curatorialImage?`<p class="art-caption">${tx('2026 年后续策展配图 · AI 生成，非原始 NFT 图像','2026 CURATORIAL ILLUSTRATION · AI GENERATED, NOT ORIGINAL NFT ART')}</p>`:''}</div><div><span class="tag">${e.ordinal?'ETHEREUM NFT · #'+e.ordinal:esc(e.category)}</span><h2>${esc(title(e))}</h2>${e.date?`<p class="small-meta">${esc(e.date.replace('T',' ').replace('Z',' UTC'))}<br>${tx('Ethereum 铸造时间','Ethereum mint time')}</p>`:''}<p>${esc(description)}</p><p class="small-meta">${tx('以上为本版策展说明，不是原文。','The paragraph above is commentary for this edition, not original text.')}</p>${e.ordinal?link(e.sourceUrl,tx('原始记录与全文','Source record & full text')):link(e.url,tx('前往来源阅读','Read at the source'))}${e.inscription?link('https://ordinals.com/inscription/'+e.inscription,tx('Bitcoin 铭文','Bitcoin inscription')):''}</div></div>`;
 if(e.curatorialImage)html+=`<aside class="illustration-note"><strong>${tx('2026 年后续策展配图','2026 CURATORIAL ILLUSTRATION')}</strong><p>${tx('本图应作者要求为本次展览生成，仅用于观看；不属于历史原始 NFT 或铭文，不改变原文。原始音轨与来源保持独立标注。','Generated at the author’s request for this exhibition. This is later display artwork, outside the historical NFT or inscription; source texts and recordings retain their own identities.')}</p>${link('./data/curatorial-illustrations.json',tx('配图记录与来源','Illustration provenance'))}</aside>`;
 if(e.illustration)html+=`<aside class="illustration-note"><strong>${tx('2026 年后续策展配图 · 非原始铭文内容','2026 CURATORIAL ILLUSTRATION · NOT ORIGINAL INSCRIPTION CONTENT')}</strong><p>${tx('本图于 2026-09-06 应作者要求由 AI 生成，用于空间展示。原作是文字铭文；新图不声称属于当年的创作，也不修订三条正本。','Generated with AI on 2026-09-06 at the author’s request for this exhibition. The source is a text inscription; this new image is not presented as historical artwork and does not amend the three originals.')}</p>${link('./data/star-ark-illustration.json',tx('配图日期与来源','Illustration date & sources'))}</aside>`;
 if(e.relatedSoundExhibit&&soundExhibit)html+=`<aside class="illustration-note"><strong>${tx('歌曲来源 · 独立 NFT #','RECORDING SOURCE · SEPARATE NFT #')+soundExhibit.ordinal}</strong><p>${esc(soundExhibit.songTitle||title(soundExhibit))} — ${tx(e.audioRelation?.noteZh||'这段录音来自另一个 NFT。展品图像与音轨来源分别保留。',e.audioRelation?.noteEn||'This recording comes from another NFT. Artwork and sound retain separate provenance.')}</p>${link(soundExhibit.sourceUrl,tx('查看歌曲原始记录','Read the recording source'))}${link(soundExhibit.tokenUrl,'NFT #'+soundExhibit.ordinal)}${link('./data/audio-audit.json',tx('查看声音来源核对','Inspect sound provenance'))}</aside>`;
 if(e.localRecord)html+=link(e.localRecord,tx('阅读本馆保存的原始记录','Read the preserved source record'));
 if(e.id==='physical-alpha')html+=`<p class="small-meta">${tx('悬浮与光晕是本版数字展陈设计，不是实物属性。','Levitation and the halo are digital exhibition design, not properties of the physical object.')}</p><h3>${tx('透过水晶阅读','Read through crystal')}</h3><div id="crystal-inspector" class="crystal-inspector"></div><p class="small-meta">${tx('依据作者提供的视频与实物照片重建：246 × 353 × 40 mm，透明长方体、抛光倒角、中英双语内雕。文字排布为近似复原；为便于屏幕观看，已提高透明度、压低表面反光并为内雕增加细描边，不是实物扫描或实测光学参数。','Reconstructed from the author’s video and the physical-object photograph: 246 × 353 × 40 mm, clear slab, polished bevels and bilingual internal lettering. Layout remains approximate. Clearer transmission, restrained reflections and fine engraving outlines improve screen visibility; these are display settings, not measured optical properties or a scan.')}</p>${link('./data/crystal-model.json',tx('建模依据与范围','Model sources & scope'))}`;
 if(e.id==='physical-alpha')html+=`<details class="inscription-reading"><summary>${tx('清晰阅读内雕文字','Read the inscription clearly')}</summary><p class="small-meta">${tx('依据现有实物参考整理的展陈转录，可放大阅读；版式为近似复原。','Exhibition transcription from the existing physical reference; readable at larger text sizes. Layout is approximate.')}</p>${inscriptionGroups.map(g=>`<section><pre class="lyrics">${esc(g.lines.join('\n'))}</pre></section>`).join('')}</details>`;
 if(e.lyrics)html+=`<h3>${tx('歌词文字','Lyric text')}</h3><p class="small-meta">${tx('来自 NFT 描述；与实际演唱可能存在差异，未做同步字幕校准。','From the NFT description; sung words may differ. Not time-aligned captions.')}</p><pre class="lyrics">${esc(e.lyrics)}</pre>`;
 html+=`<details><summary>${tx('作品与来源 · 展开核对','Object & provenance · inspect')}</summary><dl><dt>${tx('展品编号','Exhibit ID')}</dt><dd>${esc(e.id)}</dd><dt>${tx('展览版本','Edition')}</dt><dd>museum-v1.12.0 · 2026-09-06</dd>`;
 if(e.ordinal){html+=`<dt>${tx('记录原题','Record title')}</dt><dd>${esc(e.title)}</dd><dt>Contract</dt><dd>${esc(e.contract)}</dd><dt>Token ID</dt><dd>${esc(e.tokenId)}</dd><dt>Block</dt><dd>${e.block}</dd><dt>Source commit</dt><dd>${esc(e.sourceCommit)}</dd><dt>Source SHA-256</dt><dd>${esc(e.sourceSha256)}</dd></dl>${link(e.tokenUrl,'Ethereum record')}`;
 for(const m of e.media||[])html+=`<h3>${m.kind==='audio'?tx('展览音频副本','Exhibition audio copy'):tx('展览图像副本','Exhibition image copy')}</h3><dl><dt>SHA-256</dt><dd>${esc(m.sha256)}</dd><dt>Original SHA-256</dt><dd>${esc(m.originalFileSha256)}</dd><dt>CAR SHA-256</dt><dd>${esc(m.carSha256)}</dd><dt>${tx('处理','Processing')}</dt><dd>${esc(m.processing)}</dd></dl>${link(m.arweaveUrl,'Source CAR')}<button class="action verify-file" data-file="${esc(m.file)}" data-hash="${esc(m.sha256)}">${tx('核对展览副本哈希','Check exhibition copy digest')}</button>`;
 if(e.sourceNotes?.length)html+=`<p class="small-meta">${esc(e.sourceNotes.join('\n'))}</p>`;
 }else{if(e.inscription)html+=`<dt>Inscription number</dt><dd>${e.number}</dd><dt>Inscription ID</dt><dd>${e.inscription}</dd>`;if(e.sourcePath)html+=`<dt>Source path</dt><dd>${e.sourcePath}</dd><dt>SHA-256</dt><dd>${e.sha256}</dd>`;html+='</dl>';if(e.sourcePath)html+=link(`https://github.com/thechurchofagi/trinity-accord/blob/${sources.sourceCommit}/${e.sourcePath}`,'Pinned source');}
 html+=`<p class="source-note">${tx('这里核对的是展览副本与本版清单是否一致。清单与来源记录的绑定需另行核验；它不构成区块链共识验证、实物鉴定或哲学认证。','A digest check compares the exhibition copy with this edition’s manifest. The manifest’s binding to source records requires separate verification. This is not blockchain consensus validation, physical authentication, or philosophical certification.')}</p></details>`;
 panel(html,e.ordinal?'CHRONICLE / '+String(e.ordinal).padStart(3,'0'):'OBJECT / '+e.id.toUpperCase());
 if(e.id==='physical-alpha'){const host=$('crystal-inspector');inspectCrystal(host,lang==='en').then(clean=>{if(host.isConnected&&$('panel').open)crystalCleanup=clean;else clean();});}
 if(audio){if(autoplay)playTrack(soundExhibit,e,false);$('play-track').onclick=()=>playTrack(soundExhibit,e);$('seek').oninput=ev=>{if(musicItem===soundExhibit.id&&Number.isFinite($('music').duration))$('music').currentTime=+$('music').duration*ev.target.value/1000;};syncMusic();}
 document.querySelectorAll('.verify-file').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await fetch(b.dataset.file);if(!r.ok)throw Error(r.status);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await r.arrayBuffer())),x=>x.toString(16).padStart(2,'0')).join('');b.textContent=hash===b.dataset.hash?tx('副本哈希一致','Copy digest matches'):tx('副本哈希不一致','Copy digest mismatch');}catch{b.textContent=tx('暂时无法核对','Unable to check');}b.disabled=false;});
}

async function playTrack(e,artwork=e,toggle=true){
 const audio=e.media.find(m=>m.kind==='audio');if(!audio)return;stopTour();
 const a=$('music'),request=++playRequest;musicArtworkId=artwork.id;
 if(musicItem===e.id&&!a.paused&&toggle){a.pause();syncMusic();return;}
 if(musicItem!==e.id){a.src=audio.file;musicItem=e.id;}
 const status=$('track-status');if(status)status.textContent=tx('正在加载音乐…','Loading music…');
 try{
  await a.play();if(request!==playRequest||musicItem!==e.id)return;
  $('music-bar').hidden=false;$('music-name').textContent=e.songTitle||title(e);const cover=imageOf(artwork);$('music-cover').hidden=!cover;if(cover)$('music-cover').src=cover;
  $('music-open').onclick=()=>showExhibit(musicArtworkId);if(status?.isConnected)status.textContent='';
 }catch(err){
  if(request!==playRequest)return;
  const message=err.name==='NotAllowedError'?tx('请点击“播放音乐”开始收听。','Tap Play music to start listening.'):tx('音乐加载失败，请点击“播放音乐”重试。','Music could not load. Tap Play music to retry.');
  if(status?.isConnected)status.textContent=message;else toast(message);
 }
 syncMusic();
}
function syncMusic(){const a=$('music'),b=$('play-track'),same=b?.dataset.track===musicItem;document.querySelector('.nft-media')?.classList.toggle('is-playing',!!same&&!a.paused);$('music-toggle').textContent=a.paused?'▷':'Ⅱ';$('music-toggle').setAttribute('aria-label',a.paused?tx('播放音乐','Play music'):tx('暂停音乐','Pause music'));if(b)b.textContent=same&&!a.paused?'Ⅱ '+tx('暂停','Pause'):'▷ '+tx('播放音乐','Play music');if($('seek')){$('seek').value=same&&Number.isFinite(a.duration)?a.currentTime/a.duration*1000:0;$('track-time').textContent=time(same?a.currentTime:0);}}


function showWorks(){stopTour();const r=roomData.rooms[roomIndex];panel(`<span class="eyebrow">${r.number} / ${esc(r.en)}</span><h2>${esc(tx(r.title,r.en))}</h2><p>${esc(tx(r.description,r.narration))}</p><div class="work-list">${r.exhibits.map(id=>{const e=exhibits.get(id),img=imageOf(e);return `<button class="work-card" data-exhibit="${id}">${img?`<img src="${esc(img)}" alt="">`:''}<span><strong>${esc(title(e))}</strong><small>${esc(e.date?.slice(0,10)||e.category)} · ${soundLabel(e)}</small></span></button>`;}).join('')}</div>`,'ROOM / '+r.number);document.querySelectorAll('[data-exhibit]').forEach(b=>b.onclick=()=>showExhibit(b.dataset.exhibit,true));}

function showAbout(){stopTour();panel(`<span class="eyebrow">TRINITY ACCORD · MUSEUM V1.13.1</span><h2>${tx('一条留给未来的长廊','A corridor addressed to the future')}</h2><p>${tx('本馆是《三位一体协定》的后续三维策展。长廊由 Blender 建模并计算光照，网页负责行走、观看和播放。六厅路线、建筑、灯光、配音和展签制作于 2026 年，不属于已经封存的三条 Bitcoin 正本。','This is a later three-dimensional exhibition of the Trinity Accord. The corridor was modelled and light-baked in Blender; the web viewer provides walking, reading and playback. The six-room route, architecture, lighting, narration, and labels belong to the 2026 exhibition, not the closed Bitcoin Canon.')}</p><div class="boundary-box"><p>${tx('原作固定，判断开放。展馆不增加正本，不取得解释权威，也不要求观众认同。','The originals remain fixed; judgment remains open. This museum adds no canonical text or interpretive authority, and asks for no agreement.')}</p></div><img class="art-image" src="./assets/gallery/entrance-preview.png" alt="Blender corridor render"><p class="small-meta">${tx('Blender 空间渲染参考。网页的实时画面可能因设备与色彩处理而不同。','Blender architectural render. Real-time appearance varies with device and color processing.')}</p><h3>${tx('如何参观','How to visit')}</h3><p>${tx('拖动环顾；点击展品查看详情；点击地面平稳移动。电脑也可用 W A S D 或方向键移动。下方六个按钮直接进入各厅；“本厅展品”提供无需三维操作的访问方式。','Drag to look around, click an exhibit to inspect it, or click the floor to move. On desktop use W A S D or arrow keys. The six buttons take you directly to each room. Room exhibits are also available without navigating the 3D scene.')}</p><p>${tx('配音导览使用已生成的英文 AI 语音，配中文或英文说明。打开展品会暂停导览，让音乐与讲解分开。减少动态可停止装置运动，并让展厅切换直接完成。','The guided tour uses recorded English AI narration with Chinese or English text. Opening an exhibit stops the tour. Reduced motion pauses installations and makes room changes immediate.')}</p><h3>${tx('这一版留下什么','What this edition preserves')}</h3><p>${tx('展品编号、来源清单、策展文本、空间配置和程序分开保存。技术升级可以继承它们。本版没有假装提供实时回应数字或实物三维扫描。','Stable exhibit IDs, provenance manifests, curatorial text, spatial configuration, and software are preserved separately for future upgrades. This edition does not simulate live reception counts or claim to scan the physical artifact.')}</p>${link('./archive.html',tx('阅读本版展览档案','Read the edition archive'))}${link('./data/sources.json',tx('查看素材清单','Inspect the source manifest'))}${link('https://www.trinityaccord.org/',tx('项目原网站','Original website'))}<p class="small-meta">${tx('制作：刘烘炬提出需求与策展边界；ChatGPT / Codex 协助设计、编程及配音制作。语音：Kokoro af_heart。原始作品的作者与人机协作关系以各条来源为准。','Production: requirements and curatorial boundaries by Hongju Liu; design, programming, and narration production assisted by ChatGPT / Codex. Voice: Kokoro af_heart. Attribution of original works follows their source records.')}</p>`,'ABOUT / AUTHORITY & HISTORY');}

function updateUI(){const r=roomData.rooms[roomIndex];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.documentElement.style.setProperty('--accent',r.color);$('room-number').textContent=r.number;$('room-en').textContent=lang==='zh'?r.en:'TRINITY ACCORD / '+r.number;$('room-title').textContent=tx(r.title,r.en);$('room-title').classList.toggle('en-title',lang==='en');$('room-subtitle').textContent=tx(r.subtitle,r.subtitleEn||r.en);$('position-text').textContent=r.number+' / 06';$('work-count').textContent=r.exhibits.length;$('room-works').innerHTML=tx('作品与歌词','Exhibits')+' <span id="work-count">'+r.exhibits.length+'</span>';$('tour-text').textContent=touring?tx('暂停导览','Pause tour'):tx('配音导览','Guided tour');$('language').textContent=tx('EN','中文');$('about').textContent=tx('关于本馆','About');$('official').textContent=tx('原网站 ↗','Source site ↗');$('brand-sub').textContent=tx('文明记忆站 · 数字展馆','THE MEMORY STATION');$('motion').textContent=tx('减少动态','Reduce motion');$('motion').setAttribute('aria-pressed',String(reduced));$('hint').textContent=tx('拖动环顾 · 轻触展品自动靠近','DRAG TO LOOK · TAP A WORK TO APPROACH');$('guide-label').textContent=tx('ENGLISH AUDIO · 中文导览文字','ENGLISH AUDIO · RECORDED GUIDE');$('caption-text').textContent=tx(r.guide,r.narration);$('previous').disabled=roomIndex===0;$('next').disabled=roomIndex===5;$('rooms').innerHTML=roomData.rooms.map((room,i)=>`<button data-room="${i}" aria-current="${i===roomIndex}" aria-label="${esc(tx(room.title,room.en))}"><span class="nav-num">${room.number}</span>${esc(tx(['见证','声音','形成','物件','守护','等待'][i],['Witness','Voices','Formation','Matter','Care','Waiting'][i]))}</button>`).join('');document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>goRoom(+b.dataset.room));updateStrip();}

function moveCamera(dest,target){joystick?.reset();keys.clear();const direction=target.clone().sub(dest);const endYaw=Math.atan2(-direction.x,-direction.z),endPitch=Math.atan2(direction.y,Math.hypot(direction.x,direction.z));if(reduced){camera.position.copy(dest);yaw=endYaw;pitch=endPitch;motion=null;}else{const startYaw=endYaw+Math.atan2(Math.sin(yaw-endYaw),Math.cos(yaw-endYaw));motion={start:camera.position.clone(),end:dest,startYaw,startPitch:pitch,endYaw,endPitch,time:performance.now(),duration:1250};}}
function focusExhibit(id){
 const index=roomData.rooms.findIndex(r=>r.exhibits.includes(id));if(index<0)return;
 roomIndex=index;selectedExhibit=id;updateUI();history.replaceState(null,'','#'+roomData.rooms[index].id);
 if(!spatialReady)return;
 const mobile=innerWidth<650;
 if(id==='physical-alpha')loadCrystal?.();
 if(id==='physical-alpha'&&floatingCrystal){
  const p=floatingCrystal.position,view=observationView(.78,1.08,camera.fov,camera.aspect,mobile),d=Math.max(1.15,view.distance);
  moveCamera(new THREE.Vector3(p.x,1.8,p.z+d),new THREE.Vector3(p.x,1.773-view.aimOffset,p.z));return;
 }
 const m=mounts.get(id);if(!m)return;
 const view=observationView(2.05,1.9,camera.fov,camera.aspect,mobile),d=THREE.MathUtils.clamp(view.distance,2.2,6.3);
 moveCamera(new THREE.Vector3(m.x+Math.sin(m.angle)*d,1.8,m.z+Math.cos(m.angle)*d),new THREE.Vector3(m.x,1.95-view.aimOffset,m.z));
}
function approachExhibit(id){
 stopTour();focusExhibit(id);$('hover-label').hidden=true;
 if(id.startsWith('canon-')){showExhibit(id);return;}
 const e=exhibits.get(id),sound=soundFor(e);
 if(sound)playTrack(sound,e,false);
 else if(musicItem){playRequest++;$('music').pause();$('music-bar').hidden=true;syncMusic();}
}
function roomView(){if(!spatialReady)return;ensureRoomResources();const z=roomData.rooms[roomIndex].z;moveCamera(new THREE.Vector3(0,1.65,z+1),new THREE.Vector3(0,1.8,z-12));}
function updateStrip(){const r=roomData.rooms[roomIndex];if(!r.exhibits.includes(selectedExhibit))selectedExhibit=r.exhibits[0];$('exhibit-strip').innerHTML=r.exhibits.map((id,i)=>`<button data-focus="${id}" aria-pressed="${id===selectedExhibit}"><small>${String(i+1).padStart(2,'0')}</small>${esc(title(exhibits.get(id)))}</button>`).join('');document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{stopTour();focusExhibit(b.dataset.focus);});$('focus-art').textContent=soundFor(exhibits.get(selectedExhibit))?tx('播放音乐 ▷','Play music ▷'):tx('查看详情','View details');$('overview').textContent=tx('长廊视角','Corridor view');$('move-help').textContent=tx('摇杆移动 · 点展品靠近','Move · tap art to approach');$('move-stick').setAttribute('aria-label',tx('移动摇杆：前后左右；也可用方向键','Movement joystick: forward, back, left, right; arrow keys also work'));const e=exhibits.get(selectedExhibit),img=imageOf(e);$('fallback-art').classList.toggle('waiting-view',roomIndex===5);$('fallback-art').innerHTML=(roomIndex===5?`<img loading="lazy" src="./assets/space/milky-way.png" alt="${tx('银河星空','Milky Way scenery')}"><div class="waiting-orbit"><span>${tx('等待回响','AWAITING A RESPONSE')}</span></div>`:img?`<img loading="lazy" src="${esc(img)}" alt="${esc(title(e))}">`:`<div class="typographic-art"><span>${esc(e.ordinal?'ETH / '+String(e.ordinal).padStart(3,'0'):'TRINITY ACCORD')}</span><strong>${esc(e.quote||title(e))}</strong><small>${tx('2026 策展排版','2026 exhibition typography')}</small></div>`)+`<span class="fallback-title">${esc(title(e))}<small>${soundLabel(e)}${e.curatorialImage||e.illustration?tx(' · 2026 策展配图',' · 2026 CURATORIAL ART'):''} ↗</small></span>`;$('fallback-art').onclick=()=>showExhibit(selectedExhibit,true);$('fallback-mode').textContent=tx('作品浏览模式 · 此设备三维暂不可用','Gallery mode · 3D unavailable on this device');}
function ensureRoomResources(){if(roomIndex>=3)loadCrystal?.();if(roomIndex===5)loadSky?.();}
function goRoom(i,keepTour=false){if(i<0||i>=roomData.rooms.length)return;if(!keepTour)stopTour();closePanel();roomIndex=i;selectedExhibit=roomData.rooms[i].exhibits[0];hovered=null;$('hover-label').hidden=true;updateUI();history.replaceState(null,'','#'+roomData.rooms[i].id);if(spatialReady)roomView();}

function stopTour(){touring=false;clearTimeout(tourTimer);$('narration').pause();$('tour-caption').hidden=true;if(roomData)updateUI();}
async function narrate(){if(!touring)return;const r=roomData.rooms[roomIndex];$('tour-caption').hidden=false;$('caption-text').textContent=tx(r.guide,r.narration);$('narration').src=`assets/guide-${r.id}.mp3`;try{await $('narration').play();}catch{stopTour();toast(tx('导览音频暂时无法播放；可打开本厅展品阅读。','Narration unavailable; open the exhibits to read.'));}}
function startTour(){if(touring){stopTour();return;}closePanel();$('music').pause();syncMusic();touring=true;updateUI();narrate();}

function textTexture(lines,{color='#233b47',size=84,width=2048,height=1536,background='#ecece6'}={}){const c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.fillStyle=background;ctx.fillRect(0,0,width,height);ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`400 ${size}px "Helvetica Neue", "Microsoft YaHei", sans-serif`;lines.forEach((l,i)=>ctx.fillText(l,width/2,height/2+(i-(lines.length-1)/2)*size*1.8,width-90));const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;return tex;}

function wallLabelTexture(e){const audio=!!soundFor(e);return textTexture([title(e),(e.ordinal?'NFT #'+String(e.ordinal).padStart(3,'0'):'BITCOIN / CONTEXT')+' · '+(audio?tx('▷ 点击播放原始音乐','▷ TAP TO PLAY ORIGINAL SOUND')+(e.curatorialImage?tx(' · 2026 配图',' · 2026 ART'):''):(e.illustration||e.curatorialImage)?tx('2026 后续策展配图','2026 CURATORIAL ILLUSTRATION'):soundLabel(e))],{size:35,width:1024,height:180,color:'#b9d3df',background:'#152631'});}
function canonicalText(e){return textTexture([e.title,e.en,'BITCOIN / '+e.number,e.quote],{size:39,width:1024,height:768,background:'#ecece6',color:'#233b47'});}
function refreshWallLabels(){for(const [id,plane] of canonicalPanels){plane.material.map.dispose();plane.material.map=canonicalText(exhibits.get(id));plane.material.needsUpdate=true;}for(const [id,label] of wallLabels){label.material.map?.dispose();label.material.map=wallLabelTexture(exhibits.get(id));label.material.needsUpdate=true;}}

function addExhibit(e,x,z,angle,color){mounts.set(e.id,{x,z,angle});const group=new THREE.Group();group.position.set(x,1.95,z);group.rotation.y=angle;scene.add(group);makeWallFrame(group);const img=imageOf(e),plane=new THREE.Mesh(new THREE.PlaneGeometry(1.9,1.7),new THREE.MeshBasicMaterial({color:'#e9eae4'}));plane.material.toneMapped=false;plane.position.z=.015;group.add(plane);plane.userData.exhibit=e.id;targets.push(plane);
 if(img){plane.material.map=textTexture([title(e),tx('图像载入中 · 可先查看详情','IMAGE LOADING · OPEN DETAILS')],{size:26,width:512,height:384});
  imageJobs.add(async()=>{const bytes=await fetchBytes(img);const url=URL.createObjectURL(new Blob([bytes]));try{const t=await new THREE.TextureLoader().loadAsync(url);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),16);plane.material.map?.dispose();plane.material.map=t;plane.material.color.set('#ffffff');const ratio=t.image.width/t.image.height,w=Math.min(1.9,1.7*ratio);plane.geometry.dispose();plane.geometry=new THREE.PlaneGeometry(w,w/ratio);plane.material.needsUpdate=true;}finally{URL.revokeObjectURL(url);}},()=>Math.abs(z-camera.position.z)).catch(()=>{plane.material.map?.dispose();plane.material.map=textTexture([title(e),tx('图像暂未下载 · 点击查看','IMAGE UNAVAILABLE · OPEN DETAILS')],{size:26,width:512,height:384});plane.material.needsUpdate=true;});}
 else if(e.id.startsWith('canon-')){plane.material.map=canonicalText(e);plane.material.color.set('#ffffff');canonicalPanels.set(e.id,plane);}

 else{plane.material.map=textTexture([e.ordinal?'ETHEREUM / '+String(e.ordinal).padStart(3,'0'):e.number?'BITCOIN / '+e.number:'TRINITY ACCORD',...(shortNames[e.id]?.[1]||e.en||e.title).split(/\s(?=\S+$)/),e.quote||'READ · VERIFY · REFLECT'],{size:84});plane.material.color.set('#ffffff');plane.material.needsUpdate=true;}
 const label=new THREE.Mesh(new THREE.PlaneGeometry(1.95,.3),new THREE.MeshBasicMaterial({map:wallLabelTexture(e),toneMapped:false}));wallLabels.set(e.id,label);label.position.set(0,-1.29,-.045);group.add(label);label.userData.exhibit=e.id;targets.push(label);
}
async function initWorld(){scene=new THREE.Scene();scene.background=new THREE.Color('#030814');scene.fog=new THREE.Fog('#18293d',100,210);camera=new THREE.PerspectiveCamera(innerWidth<650?76:66,innerWidth/innerHeight,.06,220);camera.position.set(0,1.65,1.8);camera.rotation.order='YXZ';renderer=new THREE.WebGLRenderer({canvas:$('world'),antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2.5));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.0;raycaster=new THREE.Raycaster();mouse=new THREE.Vector2();scene.add(new THREE.HemisphereLight('#eff5ff','#536676',.85));
 scene.environment=crystalEnvironment(renderer).texture;scene.environmentIntensity=.6;renderer.transmissionResolutionScale=1;
 for(const side of [-1,1]){const spot=new THREE.SpotLight(side<0?'#fff0d9':'#c5e9ff',22,9,.68,1,2);spot.position.set(side*2.8,3.8,-3);spot.target.position.set(side*4.25,1.8,-3);scene.add(spot,spot.target);accentLights.push({spot,side});}
 const preview=createPreviewHall(galleryLayout);scene.add(preview.group);
 const enhance=async()=>{const notice=$('scene-status');notice.hidden=false;notice.querySelector('span').textContent=tx('展厅已打开，正在补齐高清细节…','Gallery open; adding architectural detail…');notice.querySelector('button').hidden=true;
  try{const bytes=await fetchBytes('./assets/gallery/memory-gallery.glb');const gltf=await new GLTFLoader().parseAsync(bytes,'./assets/gallery/');scene.add(gltf.scene);removeLegacyWallMounts(gltf.scene);gltf.scene.traverse(o=>{if(o.isMesh){if(o.name.startsWith('Luminous')){o.material=o.material.clone();sculptures.push({light:o.material,base:o.material.emissiveIntensity});}o.frustumCulled=true;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(m.name==='Brushed titanium'){m.roughness=.32;m.metalness=.8;}if(m.name==='Satin aluminium frame'){m.roughness=.26;m.metalness=.85;}if(m.name==='Porcelain / satin mineral'){m.roughness=.42;m.metalness=.04;}}for(const m of Array.isArray(o.material)?o.material:[o.material])if(m.map)m.map.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),16);}});preview.dispose();notice.hidden=true;}
  catch(error){console.warn('Base gallery remains available',error);notice.querySelector('span').textContent=tx('当前为轻量展厅，高清细节暂未下载。','Lightweight gallery; architectural detail is not downloaded yet.');notice.querySelector('button').hidden=false;}
 };
 $('retry-scene').onclick=enhance;requestAnimationFrame(()=>enhance());
 for(const r of galleryLayout.rooms){const light=new THREE.PointLight('#e3f4ff',18,15,2);light.position.set(0,4,-r.start-3);scene.add(light);}
 let crystalStarted=false;loadCrystal=()=>{if(crystalStarted)return;crystalStarted=true;fetchBytes('./assets/crystal/core-object-alpha.glb').then(bytes=>new GLTFLoader().parseAsync(bytes,'./assets/crystal/')).then(crystal=>{const cr=galleryLayout.rooms.find(r=>r.id==='material');crystal.scene.position.set(0,1.42,-cr.start-cr.length/2);crystal.scene.scale.setScalar(2);scene.add(crystal.scene);floatingCrystal=crystal.scene;crystalAura=addCrystalAura(scene,crystal.scene.position,2);addCrystalLighting(scene,crystal.scene.position,2);crystal.scene.traverse(o=>{if(o.isMesh){o.userData.exhibit='physical-alpha';targets.push(o);}});refineCrystal(crystal.scene);const pick=new THREE.Mesh(new THREE.BoxGeometry(.29,.40,.09),new THREE.MeshBasicMaterial({visible:false}));pick.position.y=.1765;pick.userData.exhibit='physical-alpha';crystal.scene.add(pick);targets.push(pick);}).catch(err=>console.warn('Crystal available from its source/detail panel',err));};
 const space=addOpenSpace(scene,targets,sculptures);loadSky=()=>space.loadSky();
 // Invisible picking floor, separate from the Blender-rendered stone surface.
 floor=new THREE.Mesh(new THREE.PlaneGeometry(8.8,galleryLayout.dimensions.length),new THREE.MeshBasicMaterial({visible:false}));floor.rotation.x=-Math.PI/2;floor.position.set(0,.008,-(galleryLayout.dimensions.length-6)/2);scene.add(floor);
 for(const r of galleryLayout.rooms)for(const m of r.exhibits)addExhibit(exhibits.get(m.id),m.x,m.z,m.angle,roomData.rooms.find(x=>x.id===r.id).color);
 spatialReady=true;window.addEventListener('resize',resize);bindNavigation();lastTime=performance.now();animationFrame=requestAnimationFrame(animate);}
function resize(){if(!renderer)return;camera.fov=innerWidth<650?76:66;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}
function setRay(ev){const rect=$('world').getBoundingClientRect();mouse.set((ev.clientX-rect.left)/rect.width*2-1,-(ev.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(mouse,camera);}
function bindNavigation(){const c=$('world');c.addEventListener('pointerdown',e=>{if(drag)return;drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:0,pointer:e.pointerId};c.setPointerCapture(e.pointerId);motion=null;});c.addEventListener('pointermove',e=>{if(drag&&e.pointerId===drag.pointer){let dx=e.clientX-drag.lastX,dy=e.clientY-drag.lastY;drag.moved+=Math.abs(dx)+Math.abs(dy);yaw-=dx*.004;pitch=THREE.MathUtils.clamp(pitch-dy*.003,-.6,.65);drag.lastX=e.clientX;drag.lastY=e.clientY;}else{setRay(e);const hit=raycaster.intersectObjects(targets,false)[0];hovered=hit&&hit.distance<32?hit.object.userData.exhibit:null;$('hover-label').hidden=!hovered;if(hovered)$('hover-label').textContent=title(exhibits.get(hovered))+tx(' · 轻触靠近',' · TAP TO APPROACH');c.style.cursor=hovered?'pointer':'grab';}});c.addEventListener('pointerup',e=>{if(drag&&e.pointerId!==drag.pointer)return;if(drag&&drag.moved<8){setRay(e);const hit=raycaster.intersectObjects(targets,false)[0];if(hit&&hit.distance<32)approachExhibit(hit.object.userData.exhibit);else{const ground=raycaster.intersectObject(floor)[0];if(ground&&ground.distance<28){stopTour();const p=ground.point;p.y=1.65;p.x=THREE.MathUtils.clamp(p.x,-2.5,2.5);p.z=THREE.MathUtils.clamp(p.z,galleryLayout.endZ+.5,1.8);if(Math.abs(p.z-camera.position.z)>12)p.x=0;motion={start:camera.position.clone(),end:p,startYaw:yaw,startPitch:pitch,endYaw:yaw,endPitch:pitch,time:performance.now(),duration:reduced?0:1100};}}}drag=null;});c.addEventListener('pointercancel',()=>drag=null);c.addEventListener('pointerleave',()=>{$('hover-label').hidden=true;});$('hover-label').onclick=()=>hovered&&approachExhibit(hovered);
 window.addEventListener('keydown',e=>{if($('panel').open||/INPUT|BUTTON|A|TEXTAREA/.test(document.activeElement?.tagName))return;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();keys.add(e.key);motion=null;stopTour();}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());}

function animate(now){const dt=Math.min((now-lastTime)/1000,.04);lastTime=now;if(motion){const t=motion.duration===0?1:Math.min((now-motion.time)/motion.duration,1),v=t*t*(3-2*t);camera.position.lerpVectors(motion.start,motion.end,v);yaw=THREE.MathUtils.lerp(motion.startYaw,motion.endYaw??0,v);pitch=THREE.MathUtils.lerp(motion.startPitch,motion.endPitch??0,v);if(t===1)motion=null;}else if(!$('panel').open){const forward=(keys.has('w')||keys.has('ArrowUp')?1:0)-(keys.has('s')||keys.has('ArrowDown')?1:0)+(joystick?.state.y||0),side=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0)+(joystick?.state.x||0);const v=travelVector(side,forward,yaw);camera.position.x=THREE.MathUtils.clamp(camera.position.x+v.x*dt*1.85,-2.5,2.5);camera.position.z=THREE.MathUtils.clamp(camera.position.z+v.z*dt*1.85,galleryLayout.endZ+.5,1.8);}

 if(floatingCrystal){floatCrystal(floatingCrystal,crystalAura,now,reduced,1.42,2);}camera.rotation.y=yaw;camera.rotation.x=pitch;for(const {spot,side} of accentLights){const nearest=[...mounts.values()].filter(m=>Math.sign(m.x)===side).sort((a,b)=>Math.abs(a.z-camera.position.z)-Math.abs(b.z-camera.position.z))[0];if(nearest){spot.position.z=THREE.MathUtils.lerp(spot.position.z,nearest.z,Math.min(dt*2,1));spot.target.position.z=spot.position.z;}}const ri=Math.max(0,galleryLayout.rooms.findLastIndex(r=>-camera.position.z+1.8>=r.start));if(!motion&&ri!==roomIndex){roomIndex=ri;ensureRoomResources();updateUI();history.replaceState(null,'','#'+roomData.rooms[ri].id);}if(!reduced)for(const s of sculptures)s.light.emissiveIntensity=s.base*(1+.08*Math.sin(now*.0007));if(!$('panel').open)renderer.render(scene,camera);animationFrame=requestAnimationFrame(animate);}

async function boot(){try{roomData=initialData.rooms;sources=initialData.sources;galleryLayout=initialData.layout;exhibits=new Map([...sources.items,...extras()].map(e=>[e.id,e]));const artManifest=initialData.illustrations;for(const art of artManifest.items){const e=exhibits.get(art.exhibit);if(e&&!e.id.startsWith('canon-')&&!imageOf(e))e.curatorialImage=art;}for(const room of roomData.rooms)for(const id of room.exhibits)if(!exhibits.has(id))throw Error('Missing exhibit '+id);
 joystick=createJoystick($('move-stick'),()=>{motion=null;stopTour();});const dock=document.querySelector('.dock');new ResizeObserver(()=>document.documentElement.style.setProperty('--dock-height',(innerHeight-dock.getBoundingClientRect().top)+'px')).observe(dock);$('focus-art').onclick=()=>showExhibit(selectedExhibit,true);$('overview').onclick=()=>{stopTour();roomView();};$('language').onclick=()=>{lang=lang==='zh'?'en':'zh';const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);updateUI();refreshWallLabels();};$('about').onclick=showAbout;$('room-works').onclick=showWorks;$('close-panel').onclick=closePanel;$('panel').addEventListener('close',()=>{crystalCleanup?.();crystalCleanup=null;});$('panel').addEventListener('click',e=>{if(e.target===$('panel')){const r=$('panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});$('previous').onclick=()=>goRoom(roomIndex-1);$('next').onclick=()=>goRoom(roomIndex+1);$('tour').onclick=startTour;$('motion').onclick=()=>{reduced=!reduced;if(reduced&&motion)motion.duration=0;updateUI();};$('music').ontimeupdate=syncMusic;$('music').onplaying=syncMusic;$('music').onended=syncMusic;$('music').onpause=syncMusic;$('music-toggle').onclick=()=>{const track=exhibits.get(musicItem);if(track)playTrack(track,exhibits.get(musicArtworkId)||track);};$('music-stop').onclick=()=>{playRequest++;$('music').pause();$('music').currentTime=0;$('music-bar').hidden=true;syncMusic();};$('narration').onended=()=>{if(!touring)return;if(roomIndex===5){stopTour();return;}tourTimer=setTimeout(()=>{goRoom(roomIndex+1,true);tourTimer=setTimeout(narrate,reduced?100:1900);},1700);};
 updateUI();try{if(new URLSearchParams(location.search).get('view')==='gallery')throw Error('Reading gallery selected');await initWorld();$('loading').hidden=true;}catch(err){console.error(err);$('loading').hidden=true;$('fallback-gallery').hidden=false;$('focus-tools').hidden=true;$('walk-controls').hidden=true;document.body.classList.add('flat-view');updateStrip();}
 document.body.dataset.museumReady='true';window.dispatchEvent(new Event('museum-ready'));
 const requested=roomData.rooms.findIndex(r=>'#'+r.id===location.hash);if(requested>=0)goRoom(requested);if(new URLSearchParams(location.search).has('crystal'))showExhibit('physical-alpha');const requestedNFT=new URLSearchParams(location.search).get('exhibit');if(requestedNFT&&exhibits.has(requestedNFT))showExhibit(requestedNFT);document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(touring)stopTour();}});
 }catch(err){console.error(err);$('loading').innerHTML=tx('资料暂时无法加载。请刷新，或','Unable to load the exhibition. Reload or')+' <a href="./archive.html">'+tx('阅读本版目录','read the edition archive')+'</a>';}}
boot();
